func PluginIdEqualFold(v string) predicate.ModerationLog {
	return predicate.ModerationLog(sql.FieldEqualFold(FieldPluginId, v))
}

// PluginIdContainsFold applies the ContainsFold predicate on the "pluginId" field.
func PluginIdContainsFold(v string) predicate.ModerationLog {
	return predicate.ModerationLog(sql.FieldContainsFold(FieldPluginId, v))
}

// HasPlugin applies the HasEdge predicate on the "plugin" edge.
func HasPlugin() predicate.ModerationLog {
	return predicate.ModerationLog(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, PluginTable, PluginColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPluginWith applies the HasEdge predicate on the "plugin" edge with a given conditions (other predicates).
func HasPluginWith(preds ...predicate.Plugin) predicate.ModerationLog {
	return predicate.ModerationLog(func(s *sql.Selector) {
		step := newPluginStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ModerationLog) predicate.ModerationLog {
	return predicate.ModerationLog(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ModerationLog) predicate.ModerationLog {
	return predicate.ModerationLog(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ModerationLog) predicate.ModerationLog {
	return predicate.ModerationLog(sql.NotPredicates(p))
}
